(() => {
  'use strict';
  const X=window.LernpassExplanations, Q=window.LernpassWorkbook, C=window.LernpassCore, W=window.LernpassWriter, F=window.LernpassFlow, U=window.LernpassUnitUI, cards=window.MEC_CARDS||[], KEY='mechatronik-lernpass.v1';
  let detailMode='detailed';try{detailMode=localStorage.getItem('mec-answer-depth')==='summary'?'summary':'detailed';}catch{}
  const PDF='https://www.wko.at/ooe/bildung-lehre/fragenkatalog-kandidat-mec-h1.pdf';
  const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',learn:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',catalog:'<path d="M4 4h6a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H4Zm16 0h-4a3 3 0 0 0-3 3v14a3 3 0 0 1 3-3h4Z"/>',pass:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 10 2 2 5-5M8 16h8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bolt:'<path d="m14 2-9 12h6l-1 8 9-13h-6l1-7Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z"/>',settings:'<path d="M9 4 8 2h8l-1 2 3 2 2 0 2 6-2 1-1 3 1 2-5 4-2-2h-3l-2 2-5-4 1-2-1-3-2-1 2-6h2Z"/><circle cx="12" cy="12" r="3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',talk:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3 1-6a8 8 0 1 1 17-5Z"/>',diagram:'<rect x="8" y="2" width="8" height="6" rx="1"/><path d="M12 8v5H4v3m8-3h8v3"/><rect x="1" y="16" width="6" height="5" rx="1"/><rect x="17" y="16" width="6" height="5" rx="1"/>'};
  const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.learn}</svg>`;
  const button=(action,text,cls='button',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
  const fmtDate=(d,short=false)=>new Date(d+'T12:00:00').toLocaleDateString('de-AT',short?{day:'numeric',month:'short'}:{day:'numeric',month:'long',year:'numeric'});
  let state=C.fresh(),route='home',storageWarning='',catalogView='cards',worksheetId=null,imageUpload=null,filters={search:'',category:'all',chapter:'all',status:'all',visual:'all'},session=null,setup=null,toastTimer;
  try{const saved=localStorage.getItem(KEY);if(saved)state=C.normalize(JSON.parse(saved),cards);}catch{storageWarning='Dein gespeicherter Stand konnte nicht geladen werden. Du kannst ein Backup importieren.';}
  let syncController=null,booting=location.protocol!=='file:';
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWarning='';syncController?.changed();return true;}catch{storageWarning='Der Browser kann den Fortschritt gerade nicht speichern. Bitte sichere ein Backup.';toast(storageWarning);return false;}}
  let ai={configured:false,connectionStatus:'loading',model:'gemini-3.1-flash-lite'},flowView=null,grading=null,gradingError='',gradingErrorFor=null;
  function openUnit(id,reread=false){const u=F.unit(state,id);if(!u)return;session=null;state.learning.activeUnitId=id;flowView={type:'unit',id,reread};save();go('learn');}
  function newUnit(ids){document.querySelector('dialog')?.close();let list=ids;if(!list){let queue=C.dailyQueue(cards,state);if(!queue.length){const known=C.planInfo(state).finalReview?new Set(F.learnedIds(state,cards)):null;queue=cards.filter(c=>!known||known.has(c.id)).sort((a,b)=>C.cardState(state,a.id).stage-C.cardState(state,b.id).stage);if(!queue.length){toast('In der Abschlussphase ist noch kein bekannter Stoff verfügbar. Öffne den Fragenkatalog oder passe den Prüfungstermin an.');return;}}list=queue.slice(0,state.plan.session).map(c=>c.id);}try{openUnit(F.createUnit(state,cards,list).id);}catch(e){toast(e.message);}}
  function openTest(id){const t=F.test(state,id);if(!t)return;session=null;state.learning.activeTestId=id;flowView={type:'test',id};gradingError='';save();go('learn');}
  function newTest(unitId){try{const t=F.createTest(state,cards,unitId,{limit:state.plan.session});openTest(t.id);}catch(e){toast(e.message);}}
  function quickTest(){try{openTest(F.createQuickTest(state,cards).id);}catch(e){toast(e.message);}}
  function flowPage(){const options={state,cards,ai,button,icon,heading};if(flowView?.type==='unit'){const unit=F.unit(state,flowView.id);if(unit)return U.unitPage({...options,unit,view:flowView,answerHTML});}if(flowView?.type==='test'){const test=F.test(state,flowView.id);if(test)return U.testPage({...options,test,drawings:drawingLinks,answerHTML,busy:grading?.testId===test.id,error:gradingErrorFor===test.id?gradingError:''});}flowView=null;return U.hub(options);}
  function visibleTest(){return flowView?.type==='test'?F.test(state,flowView.id):null;}
  function flowRender(id=grading?.testId){if(route==='learn'&&flowView?.type==='test'&&flowView.id===id)render();}
  async function requestAssessment(caseId,answer){const response=await fetch('/api/check',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({caseId,answer}),signal:AbortSignal.timeout(55000)});if(response.redirected||!response.headers.get('content-type')?.includes('application/json'))throw new Error('Bitte erneut mit deinem ChatGPT-Konto anmelden. Deine Testantworten bleiben gespeichert.');const data=await response.json();if(!response.ok){const error=new Error(data.error||'Die Bewertung konnte nicht abgeschlossen werden.');error.code=data.code;error.retryAfterMs=data.retryAfterMs;throw error;}return data;}
  async function gradeTest(id){
    if(!ai.configured)return;if(grading){toast('Die laufende Testbewertung wird zuerst abgeschlossen.');return;}const ownerState=state,t=F.test(state,id);if(!t||t.status!=='submitted')return;
    grading={testId:id};gradingError='';gradingErrorFor=id;flowRender();
    try{for(const cardId of t.ids){if(state!==ownerState)break;const entry=t.entries[cardId];if(entry.assessment)continue;const card=cards.find(c=>c.id===cardId);if(Q.isVisual(card))continue;let result;
      if(!entry.answer.trim())result=F.unanswered(card);
      else{if(!ai.configured)throw new Error('Die Gemini-Bewertung ist noch nicht aktiviert. Deine abgegebenen Antworten bleiben gespeichert.');try{result=await requestAssessment(cardId,entry.answer);}catch(e){if(e.code!=='rate_limit')throw e;gradingError='Kurze Pause für das Anfragelimit. Die Bewertung läuft gleich weiter.';flowRender();await new Promise(resolve=>setTimeout(resolve,Math.min(65000,Math.max(1000,e.retryAfterMs||61000))));if(state!==ownerState)break;result=await requestAssessment(cardId,entry.answer);gradingError='';}}
      if(state!==ownerState)break;if(F.applyAssessment(state,id,card,result)){if(result.verdict!=='unclear')C.review(state,cardId,result.verdict==='correct'?'good':result.verdict==='partial'?'hard':'again');if(entry.answer.trim())C.saveAnswer(state,cardId,entry.answer,true);save();flowRender();}
    }}catch(e){gradingError=e?.name==='TimeoutError'?'Die KI hat nicht rechtzeitig geantwortet. Bereits bewertete Fragen sind gespeichert. Du kannst die Bewertung fortsetzen.':e?.name==='TypeError'?'Die Verbindung ist unterbrochen. Dein Test bleibt gespeichert.':e.message||'Die Bewertung wurde unterbrochen. Dein Test bleibt gespeichert.';}
    finally{grading=null;flowRender(id);aiStatus();}
  }
  function askTestSubmit(){const t=visibleTest();if(!t||t.status!=='draft')return;const missing=t.ids.filter(id=>!t.entries[id].answer.trim()).length;modal('Test abgeben',`<p>${t.ids.length-missing} von ${t.ids.length} Fragen beantwortet. ${missing?`<strong>${missing} ${missing===1?'Antwort ist':'Antworten sind'} noch leer.</strong> Leere Textantworten werden als noch zu üben gesammelt; Bildfragen warten auf deinen eigenen Vergleich.`:'Alle Antworten sind bereit für die Bewertung.'}</p><p>Nach der Abgabe bleiben die Antworten für diesen Test fest. Nur Textfragen gehen mit den Fachpunkten an Google Gemini. Bild- und Skizzenfragen vergleichst und bewertest du selbst anhand der Vorlage.</p><div class="button-row">${button('test-confirm-submit','Abgeben & bewerten','button primary')}${button('close-dialog','Weiter bearbeiten','button secondary')}</div>`);}
  async function aiStatus(){try{const r=await fetch('/api/check/status',{credentials:'same-origin',cache:'no-store'});if(r.ok&&r.headers.get('content-type')?.includes('application/json'))ai=await r.json();}catch{ai={...ai,configured:false,connectionStatus:'error',message:'Verbindung unterbrochen. Selbstvergleich bleibt möglich.'};}updateAiBadge();if(route==='learn'&&!$('scratchAnswer')&&!$('testAnswer'))render();}
  async function checkAnswer(){if(!session||session.mode!=='write'||session.checking)return;if(!ai.configured){personalAiDialog();return;}const active=session,position=active.position,id=active.ids[position];const text=active.scratch||'';if(Q.isVisual(cards.find(c=>c.id===id))){toast('Diese Bildfrage bitte mit der Vorlage vergleichen und selbst einschätzen.');return;}if(text.trim().length<5){toast('Bitte mindestens fünf Zeichen in deinen eigenen Worten eingeben.');return;}C.saveAnswer(state,id,text,true);save();active.submitted=true;active.checking=true;active.checkError='';active.assessment=null;render();try{const r=await fetch('/api/check',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({caseId:id,answer:text}),signal:AbortSignal.timeout(55000)});if(r.redirected||!r.headers.get('content-type')?.includes('application/json'))throw new Error('Bitte erneut mit deinem ChatGPT-Konto anmelden. Deine Antwort bleibt gespeichert.');const data=await r.json();if(!r.ok)throw new Error(data.error||'Die Prüfung konnte nicht abgeschlossen werden.');ai.configured=true;if(!data.verdict||!Array.isArray(data.points)||!data.summary)throw new Error('Die Bewertung war nicht eindeutig lesbar.');if(session===active&&active.position===position)active.assessment=data;}catch(e){if(session===active&&active.position===position)active.checkError=e?.name==='TimeoutError'?'Die Prüfung dauert zu lange. Deine Antwort bleibt gespeichert.':e?.name==='TypeError'?'Die Verbindung ist unterbrochen. Deine Antwort bleibt gespeichert.':e.message||'Die Prüfung konnte nicht abgeschlossen werden.';}finally{active.checking=false;if(session===active&&active.position===position&&route==='learn')render();}}
  function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5500);}
  function go(next){route=next;render();window.scrollTo({top:0,behavior:'instant'});$('main')?.focus({preventScroll:true});}
  const categoryStyle=cat=>({'Pneumatik':'air','Mechanik':'mechanic','Elektrotechnik':'electric','Automation':'auto','Sicherheit':'safety'}[cat]||'');
  function chapter(id){return id[0]==='D'?'Komponenten':'Modulbezogene Arbeiten';}
  function sourceLink(page,label='Original im WKO-Katalog'){return `<a class="text-link" href="${PDF}#page=${page}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('arrow')}</a>`;}
  function stageDots(stage){return `<span class="stage-dots" aria-label="Lernstufe ${stage} von 5">${[1,2,3,4,5].map(n=>`<i class="${n<=stage?'filled':''}"></i>`).join('')}</span>`;}
  function shell(content){const info=C.planInfo(state),s=C.stats(cards,state),nav=[['home','home','Übersicht'],['learn','learn','Lernen'],['catalog','catalog','Fragenkatalog'],['pass','pass','Mein Lernpass']];return `<div class="app-shell"><aside class="sidebar"><a href="#home" class="brand" data-route="home"><span class="brand-mark">m<span>·</span></span><span>mechatronik<small>DEIN LERNPASS</small></span></a><div class="sidebar-label">DEIN LERNRAUM</div><nav class="side-nav" aria-label="Hauptnavigation">${nav.map(([key,i,label])=>`<a href="#${key}" data-route="${key}" class="nav-item ${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='learn'&&s.due?`<span class="count">${s.due}</span>`:''}</a>`).join('')}</nav><div class="sidebar-plan"><span class="tiny-label">${info.examDate?"DEIN PRÜFUNGSPLAN":"DEIN "+state.plan.days/7+"-WOCHEN-PLAN"}</span><strong>${info.started?'Tag '+Math.min(Math.max(1,info.day),info.days):'Start am '+fmtDate(state.plan.start,true)} <span>/ ${info.days}</span></strong><div class="track"><i style="width:${s.percent}%"></i></div><p>${s.percent}% deiner Lernstufen erreicht</p>${button('profile','Lernprofil anpassen '+icon('arrow'),'link-button')}</div><a class="source-side" href="${PDF}" target="_blank" rel="noopener noreferrer">MEC H1 · Kapitel D & E<br><span>WKO-Katalog · 02/2024 ↗</span></a><div class="sidebar-bottom">${button('settings',icon('settings')+'<span>Einstellungen & Backup</span>','nav-item')}</div></aside><div class="workspace"><header class="topbar"><div class="crumb">Lernraum <span>/</span> <b>${nav.find(n=>n[0]===route)?.[2]||'Lernen'}</b></div><div class="top-actions">${syncBadge()}${aiBadge()}<span class="streak">${icon('bolt')} ${s.streak} ${s.streak===1?'Lerntag':'Lerntage'} in Folge</span>${button('settings',icon('settings'),'icon-button','aria-label="Einstellungen und Backup"')}<span class="avatar" title="Dein Lernprofil">DU</span></div></header><main id="main" tabindex="-1">${storageWarning?`<div class="notice warning">${esc(storageWarning)}</div>`:''}${content}</main><footer class="app-footer"><span>Eigene Lernhilfen · kein offizieller Lösungsschlüssel</span><button data-action="about" class="link-button">Quellen & Lernmethode</button></footer></div><nav class="mobile-nav" aria-label="Mobile Hauptnavigation">${nav.map(([key,i,label])=>`<a href="#${key}" data-route="${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(i)}<span>${key==='catalog'?'Katalog':key==='pass'?'Lernpass':label}</span></a>`).join('')}</nav></div>`;}
  function ring(percent,label){return `<div class="progress-ring" style="--progress:${percent}" role="img" aria-label="${percent}% ${esc(label)}"><div><strong>${percent}<small>%</small></strong><span>${label}</span></div></div>`;}
  function heading(kicker,title,sub,aside=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${aside}</div>`;}
  function estimate(){const studyDays=Array.from({length:state.plan.days},(_,n)=>C.addDays(state.plan.start,n)).filter(d=>state.plan.weekdays.includes(C.weekday(d))).length;return {studyDays,budget:studyDays*state.plan.minutes,need:Math.round(cards.length*9)};}
  function home(){const s=C.stats(cards,state),p=C.planInfo(state),queue=s.queue,newCount=queue.filter(c=>C.cardState(state,c.id).reps===0).length,minutes=Math.ceil(newCount*3+(queue.length-newCount)*1.4),last=s.byCategory.filter(c=>c.total).sort((a,b)=>a.percent-b.percent)[0];return `${heading('DEIN WISSEN. DEIN TEMPO.','Ein Schritt näher<br>zur <em>Lehrabschlussprüfung.</em>','Ein klarer Plan, kleine Lerneinheiten und genau die Wiederholungen, die du brauchst.',`<div class="heading-tools">${button('exam-plan',icon('calendar')+' Prüfungstermin & Lernplan','button primary')}<div class="date-chip">${icon('calendar')}<span>${new Date().toLocaleDateString('de-AT',{weekday:'long',day:'numeric',month:'long'})}</span></div></div>`)}<section class="dashboard-grid"><div class="hero-card"><div class="hero-copy"><span class="light-pill">${icon('spark')} FÜR DICH ZUSAMMENGESTELLT</span><h2>${queue.length?'Deine nächste<br>Lerneinheit wartet.':'Gut gemacht.<br>Heute ist Luft zum Festigen.'}</h2><p>${queue.length?`${Math.min(state.plan.session,queue.length)} ausgewählte Fälle. Erst die Fragen mit Antworten lernen, danach im Test selbst erklären. Lücken kommen in spätere Tests zurück.`:'Keine fälligen Karten im Tagesplan. Du kannst eine weitere Lerneinheit lesen oder deinen letzten Test öffnen.'}</p><div class="hero-meta"><span>${icon('clock')} ${Math.max(5,Math.round(Math.min(state.plan.session,Math.max(1,queue.length))*2.5))}–${Math.max(10,Math.round(Math.min(state.plan.session,Math.max(1,queue.length))*3.5))} Min.</span><span>${icon('learn')} ${p.phase}</span></div>${button(queue.length?'start':'exam',queue.length?'Jetzt lernen '+icon('arrow'):'Lerneinheit öffnen '+icon('arrow'),'button light')}</div><div class="hero-art" aria-hidden="true"><div class="art-grid"></div><div class="art-card back"><div class="mini-bars"><i></i><i></i><i></i></div></div><div class="art-card front"><span class="art-check">${icon('check')}</span><i></i><i></i><i></i><div class="art-dots"><b></b><b></b><b></b><b></b><b></b></div></div><div class="orbit one"></div><div class="orbit two"></div><span class="art-tag">Einfach. Schritt für Schritt.</span></div></div><div class="today-card panel"><div class="section-top"><h2>Heute im Fokus</h2><span class="soft-icon">${icon('check')}</span></div>${ring(s.target?Math.min(100,Math.round(s.today/s.target*100)):0,'TAGESZIEL')}<div class="today-count"><strong>${s.today}</strong> / ${s.target||'–'} Fälle bearbeitet</div><div class="today-detail"><span><i class="dot green"></i> ${s.due} Wiederholungen</span><span><i class="dot blue"></i> ${newCount} neue Fälle</span></div><p class="small-muted">${p.studyDay?`Tagespensum ca. ${minutes} Min. · ${state.plan.minutes} Min. eingeplant`:'Heute ist ein freier Tag. Wiederholen bleibt freiwillig möglich.'}</p></div></section><div class="stats-row">${[['catalog','94','Prüfungsfälle','Kapitel D und E'],['pass',s.mastered,'Sicher erinnert','auf fünf Lernstufen'],['bolt',s.seen,'Bereits entdeckt','Schritt für Schritt aufbauen'],['calendar',p.remaining,'Tage im Plan',fmtDate(p.end,true)+' · dein Lernziel']].map(([i,n,l,t])=>`<div class="stat-card"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><span>${l}</span><small>${t}</small></div></div>`).join('')}</div>${window.LernpassPlannerUI.render({state,cards,button,icon,fmtDate})}<section class="lower-grid"><div class="panel"><div class="section-top"><div><div class="eyebrow">DEINE THEMEN</div><h2>Wissen wächst in Etappen.</h2></div>${button('catalog','Alle ansehen '+icon('arrow'),'text-link')}</div><div class="topic-list">${s.byCategory.filter(t=>t.total).map((t,n)=>`<button class="topic-row" data-action="topic" data-category="${t.category}"><span class="topic-icon ${categoryStyle(t.category)}">${icon(['diagram','settings','bolt','learn','shield'][n])}</span><span class="topic-copy"><strong>${t.category}</strong><span>${t.seen} von ${t.total} Fällen entdeckt</span></span><span class="topic-progress"><span>${t.percent}%</span><i><b style="width:${t.percent}%"></b></i></span>${icon('arrow')}</button>`).join('')}</div></div><div class="right-stack"><div class="panel personal-tip"><span class="soft-icon green">${icon('spark')}</span><div class="eyebrow">DEIN PERSÖNLICHER IMPULS</div><h2>${state.plan.formats.includes('speak')?'Erklär es, als wärst du schon im Fachgespräch.':state.plan.formats.includes('structure')?'Erst den Zusammenhang. Dann die Einzelteile.':'Mach aus Theorie einen Fall aus der Werkstatt.'}</h2><p>${state.plan.formats.includes('speak')?'Sprich deine Antwort zuerst laut aus. Der Erklärmodus gibt dir dafür Ruhe und einen kurzen Timer.':state.plan.formats.includes('structure')?'Nutze die gegliederten Teilantworten und öffne bei Bildfragen das passende Original. Danach ohne Hilfe wiederholen.':'Nenne bei jeder Antwort ein Beispiel aus deinem Betrieb. So wird aus einem Begriff eine verständliche Anwendung.'}</p>${button('start-speak','Erklärmodus ausprobieren '+icon('arrow'),'text-link')}</div><div class="panel next-topic"><span class="tiny-label">ALS NÄCHSTES VERTIEFEN</span><h3>${last?.category||'Deine Grundlagen'}</h3><p>Deine Einstufung und deine tatsächlichen Wiederholungen bestimmen, was zuerst kommt.</p>${button('weak','Unsichere Fälle üben '+icon('arrow'),'text-link')}</div></div></section>`;}
  function learnPage(){if(session)return sessionPage();return flowPage();}
  function drawingLinks(card){const pages=card.imagePages||[card.imagePage];return pages.filter(Boolean).map(page=>sourceLink(page,'Originalabbildung · Seite '+page)).join(' ');}
  function memoryHTML(card){return `<div class="memory-box">${icon('spark')}<div><strong>Dein Merksatz</strong><p>${esc(card.mnemonic)}</p></div></div>`;}
  function answerBody(card){return detailMode==='summary'?X.summaryHTML(card)+`<div class="memory-box"><strong>Merksatz</strong><p>${esc(card.mnemonic)}</p></div>`:fullAnswerHTML(card)+X.detailedHTML(card);}
  function answerHTML(card){return `<div class="answer-explanation" data-answer-id="${card.id}">${X.switchHTML(detailMode)}<div class="answer-explanation-body">${answerBody(card)}</div></div>`;}
  function fullAnswerHTML(card){return `<div class="answer-content">${state.plan.formats.includes('compact')?memoryHTML(card):''}${card.answer.map((a,i)=>`<section class="answer-part"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(a.label)}</h3><p>${esc(a.text)}</p></div></section>`).join('')}${state.plan.formats.includes('compact')?'':memoryHTML(card)}<div class="pitfall"><strong>Darauf achten</strong><p>${esc(card.pitfall)}</p></div>${card.imagePage?`<div class="drawing-note">${icon('diagram')}<div><strong>Mit Originalabbildung üben</strong><p>Öffne Seite ${card.imagePage} und benenne die Bauteile oder erkläre die Verbindung selbst.</p>${drawingLinks(card)}</div></div>`:''}<details class="sources"><summary>Fachquellen & Zuordnung</summary><p>Zuordnung: ${card.id} · ${chapter(card.id)} · Originalseite ${card.pdfPage}. Eigene Formulierung.</p>${sourceLink(card.pdfPage)}${card.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</details></div>`;}
  function sessionPage(){if(session.done)return sessionSummary();if(session.mode==='write'){const card=cards.find(c=>c.id===session.ids[session.position]);if(!card)return sessionSummary();return W.render({card,current:C.cardState(state,card.id),session,icon,button,drawings:card.imagePage?drawingLinks(card):'',reference:session.revealed?answerHTML(card):'',ai});}const card=cards.find(c=>c.id===session.ids[session.position]);if(!card){session.done=true;return sessionSummary();}const s=C.cardState(state,card.id),progress=Math.round(session.position/session.ids.length*100);return `<div class="session-top">${button('end-session',icon('back')+' Training beenden','link-button')}<span>${session.mode==='exam'?'PRÜFUNGSSIMULATION':session.mode==='speak'?'ERKLÄRMODUS':'DEINE LERNEINHEIT'}</span><b id="sessionTimer">${session.mode==='exam'?'15:00':session.mode==='speak'?'01:00 · erklären':'In deinem Tempo'}</b></div><div class="session-track"><i style="width:${progress}%"></i></div><div class="session-counter">Fall ${session.position+1} von ${session.ids.length} <span>· ${session.mode==='exam'?'Selbsteinschätzung, keine offizielle Prüfungsnote':'Stufe '+s.stage+' von 5'}</span></div><article class="study-card panel"><div class="card-labels"><span class="case-id">${card.id}</span><span class="tag ${categoryStyle(card.category)}">${card.category}</span>${Q.isVisual(card)?'<span class="visual-badge">Bild / Skizze</span>':''}${button('favorite',icon('star'),'icon-button '+(s.favorite?'is-favorite':''),`data-id="${card.id}" aria-label="${s.favorite?'Favorit entfernen':'Als Favorit merken'}" aria-pressed="${s.favorite}"`)}</div><h1>${esc(card.title)}</h1><p class="study-question">${esc(card.question)}</p><div class="recall-box">${icon(session.mode==='speak'?'talk':'learn')}<span>${session.mode==='speak'?'Sprich frei für etwa eine Minute. Nenne ein Praxisbeispiel und erkläre den Zusammenhang.':state.plan.formats.includes('practice')?'Formuliere die Antwort selbst und nenne ein Beispiel aus deinem Betrieb.':state.plan.formats.includes('structure')?'Gliedere deine Antwort: Aufgabe, Aufbau, Funktion und mögliche Fehler.':'Formuliere die Antwort zuerst selbst. Was würdest du im Fachgespräch sagen?'}</span></div>${!session.revealed&&card.imagePage?`<div class="recall-drawing">${drawingLinks(card)}</div>`:''}<label class="field-label" for="scratchAnswer">Deine Antwort <span>optional · nur für diese Karte</span></label><textarea id="scratchAnswer" rows="3" placeholder="Stichpunkte oder eine freie Erklärung …">${esc(session.scratch||'')}</textarea>${session.revealed?answerHTML(card):`<div class="reveal-row">${button('reveal',icon('eye')+' Musterantwort aufdecken','button primary')}<small>Selbst erinnern ist der wichtigste Schritt.</small></div>`}</article>${session.revealed?`<section class="rating-panel" aria-label="Antwort einschätzen"><div><h2>Wie sicher war deine Antwort?</h2><p>Bewerte, was du vor dem Aufdecken wusstest.</p></div><div class="rating-buttons">${button('grade','<b>Nochmal</b><small>heute wiederholen</small>','rating again','data-grade="again"')}${button('grade','<b>Unsicher</b><small>morgen festigen</small>','rating hard','data-grade="hard"')}${button('grade','<b>Gewusst</b><small>Abstand vergrößern</small>','rating good','data-grade="good"')}</div></section>`:''}`;}
  function sessionSummary(){const s=C.stats(cards,state),good=session.results.filter(r=>r.grade==='good').length,total=session.results.length;return `<div class="session-summary panel"><span class="success-icon">${icon('check')}</span><div class="eyebrow">${session.mode==='exam'?'SIMULATION ABGESCHLOSSEN':'EIN SCHRITT GESCHAFFT'}</div><h1>${total?'Gut, dass du drangeblieben bist.':'Bis zur nächsten Lerneinheit.'}</h1><p>${total} ${total===1?'Antwort':'Antworten'} eingeschätzt, davon ${good} sicher erinnert.<br>${session.mode==='exam'?'Dies ist deine Selbsteinschätzung, keine offizielle Prüfungsnote.':'Deine nächsten Wiederholungen sind eingeplant und gespeichert.'}</p><div class="summary-stats"><span><b>${s.percent}%</b>Lernfortschritt</span><span><b>${s.streak}</b>Lerntage in Folge</span><span><b>${s.queue.length}</b>Fälle im Tagesplan</span></div><div class="button-row">${button('session-home','Zur Übersicht '+icon('arrow'),'button primary')}${button('another','Weiterlernen','button secondary')}</div></div>`;}
  function catalogPage(){return `${heading('ALLE FRAGEN. KLAR GEORDNET.','Dein Wissen <em>zum Nachschlagen.</em>','94 eigene Lernfälle mit Teilantworten, Merksätzen und Fachquellen. Zugeordnet zum verlinkten MEC-H1-Katalog.')}${Q.toolbar({state,cards,view:catalogView,button,icon,filters})}${X.switchHTML(detailMode,true)}<div class="catalog-controls panel"><div class="search-field">${icon('search')}<input id="catalogSearch" type="search" placeholder="Thema, Begriff oder Nummer suchen …" aria-label="Fragen suchen" value="${esc(filters.search)}"></div><div class="filter-row"><label>Kapitel<select id="chapterFilter"><option value="all">D & E · alle Fälle</option><option value="D" ${filters.chapter==='D'?'selected':''}>D · Komponenten</option><option value="E" ${filters.chapter==='E'?'selected':''}>E · Modulbezogene Arbeiten</option></select></label><label>Lernstand<select id="statusFilter">${[['all','Alle Lernstände'],['new','Noch neu'],['weak','Unsichere Fälle'],['favorite','Favoriten'],['mastered','Sicher erinnert'],['learned','Bereits gelernt'],['own-empty','Eigene Antwort offen'],['own-started','Eigene Antwort begonnen'],['own-complete','Selbst ausgefüllt']].map(([v,l])=>`<option value="${v}" ${filters.status===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="filter-chips" aria-label="Themen filtern">${['all',...C.CATEGORIES].map(c=>button('filter-category',c==='all'?'Alle Themen':c,'filter-chip '+(filters.category===c?'active':''),`data-category="${c}" aria-pressed="${filters.category===c}"`)).join('')}</div></div><div id="catalogResults">${catalogResults()}</div>`;}
  function cardsResults(){const list=catalogSelection();return `<div class="results-heading"><span>${list.length} ${list.length===1?'Lernfall':'Lernfälle'}</span>${button('train-filter','Diese Auswahl lernen '+icon('arrow'),'text-link',list.length?'':'disabled')}</div><div class="catalog-grid">${list.map(card=>{const s=C.cardState(state,card.id);return `<article class="catalog-card panel"><div class="card-labels"><span class="case-id">${card.id}</span><span class="tag ${categoryStyle(card.category)}">${card.category}</span>${Q.isVisual(card)?'<span class="visual-badge">Bild / Skizze</span>':''}${button('favorite',icon('star'),'icon-button '+(s.favorite?'is-favorite':''),`data-id="${card.id}" aria-label="${s.favorite?'Favorit entfernen':'Als Favorit merken'}: ${esc(card.title)}" aria-pressed="${s.favorite}"`)}</div><button class="card-open" data-action="open-card" data-id="${card.id}"><h2>${esc(card.title)}</h2><p>${esc(card.question)}</p></button><div class="catalog-card-bottom"><span>${stageDots(s.stage)}<small>${C.STAGE_NAMES[s.stage]} · ${Q.status(state,card.id)==='complete'?'Selbst ausgefüllt':Q.status(state,card.id)==='started'?'Eigene Antwort begonnen':'Eigene Antwort offen'}</small></span>${button('worksheet-open','Ausfüllen','text-link',`data-id="${card.id}"`)}${button('open-card',icon('arrow'),'icon-button',`data-id="${card.id}" aria-label="${esc(card.title)} öffnen"`)}</div></article>`;}).join('')||'<div class="empty-state panel"><h2>Hier ist noch Platz.</h2><p>Mit anderen Filtern findest du weitere Lernfälle.</p></div>'}</div>`;}
  function passPage(){const s=C.stats(cards,state),p=C.planInfo(state),today=C.today(),days=Array.from({length:p.days},(_,n)=>C.addDays(state.plan.start,n));return `${heading('DEIN PERSÖNLICHER LERNPASS','Jeder kleine Schritt <em>zählt.</em>',`${p.examDate?"Prüfung am "+fmtDate(p.examDate):state.plan.days/7+" Wochen"} · ${fmtDate(state.plan.start)} bis ${fmtDate(p.end)}. Dein Plan berücksichtigt Vorwissen, Lernzeit und Wiederholungen.`,button('exam-plan',icon('calendar')+' Prüfungstermin','button secondary'))}<div class="passport-grid"><section class="panel passport-overview"><div class="section-top"><div><div class="eyebrow">MEC H1 · KAPITEL D & E</div><h2>Dein Lernfortschritt</h2></div><span class="pass-stamp">LERN<br>PASS</span></div><div class="passport-numbers">${ring(s.percent,'LERNSTUFEN')}<div><strong>${s.mastered}<span> / ${cards.length}</span></strong><p>Fälle auf Stufe 5</p><small>Mehrfach an unterschiedlichen Tagen erinnert.<br>Eine Lernhilfe, keine Prüfungszertifizierung.</small></div></div><div class="stage-key">${C.STAGE_NAMES.map((label,i)=>`<div><span class="stage-number ${i===5?'ready':''}">${i===5?icon('check'):i}</span><span><b>${label}</b><small>${cards.filter(c=>C.cardState(state,c.id).stage===i).length} Fälle</small></span></div>`).join('')}</div></section><section class="panel profile-card"><div class="eyebrow">SO LERNST DU GERADE</div><h2>Dein Plan hat ein Profil.</h2><div class="profile-line">${icon('clock')}<span><b>${state.plan.minutes} Minuten</b> eingeplant pro Lerntag</span></div><div class="profile-line">${icon('learn')}<span><b>${state.plan.session} Fälle</b> pro kompakter Einheit</span></div><div class="profile-line">${icon('calendar')}<span><b>${state.plan.weekdays.length} Tage</b> pro Woche verfügbar</span></div><div class="format-tags">${state.plan.formats.map(f=>`<span class="tag">${formatNames[f]}</span>`).join('')}</div><p>Unsichere Themen kommen früher dran. Was du sicher erinnerst, wartet länger. Deine Übungsvorlieben bestimmen die Hinweise, keine feste „Lerntyp“-Schublade.</p>${button('profile','Einstiegscheck wiederholen '+icon('arrow'),'text-link')}</section></div><section class="panel calendar-panel"><div class="section-top"><div><div class="eyebrow">DEIN ${p.days}-TAGE-WEG</div><h2>${p.phase}</h2></div><span class="small-muted">${s.streak} ${s.streak===1?'Lerntag':'Lerntage'} in Folge</span></div><div class="calendar-grid">${days.map((day,n)=>{const count=new Set(state.history.filter(h=>h.day===day).map(h=>h.id)).size,free=!state.plan.weekdays.includes(C.weekday(day));return `<button class="day-cell ${day===today?'today':''} ${count?'completed':''} ${free?'free':''}" data-action="day" data-day="${day}" aria-label="Tag ${n+1}, ${fmtDate(day)}, ${count} Fälle bearbeitet${free?', freier Tag':''}"><span>${new Date(day+'T12:00:00').toLocaleDateString('de-AT',{weekday:'short'})}</span><b>${String(n+1).padStart(2,'0')}</b><small>${count?icon('check'):free?'frei':fmtDate(day,true)}</small></button>`;}).join('')}</div><div class="calendar-legend"><span><i class="dot green"></i> gelernt</span><span><i class="dot blue"></i> heute</span><span><i class="dot gray"></i> freier Tag</span></div></section><div class="phase-grid">${[['01','Grundlagen aufbauen','Neue Fälle kennenlernen und erste Lücken finden.'],['02','Wissen festigen','Wiederholen, eigene Beispiele nennen und Zusammenhänge erklären.'],['03','Fachgespräch trainieren','Gemischte Fälle frei beantworten. Unsicheres gezielt nacharbeiten.']].map(([n,t,text])=>`<section class="panel phase"><span>${n}</span><h3>${t}</h3><p>${text}</p></section>`).join('')}</div><div class="button-row print-actions">${button('export',icon('download')+' Lernstand sichern','button secondary')}${button('print',icon('pass')+' Lernpass drucken','button secondary')}</div>`;}
  const formatNames={practice:'Praxisbeispiele',structure:'Klare Struktur',speak:'Laut erklären',compact:'Kurz & übersichtlich'};
  const diagnostics=[
    {category:'Pneumatik',q:'Eine Pneumatikanlage ist abgeschaltet. Was kann trotzdem noch eine Bewegung auslösen?',options:['Gespeicherte Druckluft oder eine ungesicherte Last.','Nach dem Abschalten kann nichts mehr passieren.','Nur das Öffnen einer elektrischen Sicherung.'],correct:0,why:'Abschalten allein beseitigt keine gespeicherte Energie. Druck und Lasten müssen berücksichtigt werden.'},
    {category:'Mechanik',q:'Welche Aussage passt zur Festigkeitsklasse 8.8 einer Schraube?',options:['8 mm Durchmesser und 8 mm Länge.','Mindestens 800 N/mm² Zugfestigkeit und 640 N/mm² Streckgrenze.','Sie ist achtmal wiederverwendbar.'],correct:1,why:'Die erste Zahl × 100 ergibt die Mindestzugfestigkeit. Die zweite Zahl / 10 ist das Streckgrenzenverhältnis.'},
    {category:'Elektrotechnik',q:'Ein Drucktransmitter bildet seinen Messbereich auf 4–20 mA ab. Was entspricht normalerweise dem unteren Messbereichswert?',options:['0 mA.','20 mA.','4 mA.'],correct:2,why:'4 mA ist der „lebende Nullpunkt“. Ein deutlich kleinerer Strom kann einen Fehler anzeigen.'},
    {category:'Automation',q:'Was ist bei einem SPS-Funktionsbaustein (FB) im Vergleich zu einer Funktion (FC) besonders?',options:['Ein FB besitzt Instanzdaten, die zwischen Aufrufen erhalten bleiben können.','Ein FB darf grundsätzlich keine Eingänge besitzen.','Eine FC benötigt immer einen eigenen Instanz-Datenbaustein.'],correct:0,why:'FB-Instanzdaten ermöglichen einen gespeicherten Zustand. Eine FC besitzt keinen eigenen Instanzspeicher.'},
    {category:'Sicherheit',q:'Wie gehst du an eine Störung an einer Maschine heran?',options:['Zuerst Schutzfunktionen überbrücken.','Gefährdungen klären, Anlage bei Bedarf sicher stillsetzen und systematisch diagnostizieren.','Sofort verdächtige Teile austauschen, ohne den Fehler einzugrenzen.'],correct:1,why:'Sicherheit und eine nachvollziehbare Diagnose kommen vor dem Austausch. Schutzfunktionen werden nicht als Abkürzung überbrückt.'}
  ];
  function openSetup(){document.querySelector('dialog')?.close();setup={step:0,quizIndex:0,choices:Array(5).fill(null),plan:JSON.parse(JSON.stringify(state.plan))};render();window.scrollTo(0,0);}
  function setupPage(){if(!setup)setup={step:0,quizIndex:0,choices:Array(5).fill(null),plan:JSON.parse(JSON.stringify(state.plan))};const p=setup.plan,step=setup.step;let body='';
    if(step===0)body=`<div class="eyebrow">SCHRITT 1 · DEIN PRÜFUNGSZIEL</div><h1>Dein Prüfungstermin.<br><em>Dein persönlicher Lernplan.</em></h1><p class="setup-intro">Trage deinen echten Termin und deine verfügbare Zeit ein. Daraus entsteht dein Tagesplan mit neuen Fragen, Wiederholungen und einer letzten Abschlussrunde.</p><div class="setup-exam-date"><label class="field-label" for="setupDeadline">Wann ist deine Prüfung?<input id="setupDeadline" type="date" min="${C.addDays(C.today(),1)}" max="${C.addDays(p.start,366)}" value="${p.deadline||''}"></label><small>Noch kein Datum? Lass das Feld leer und wähle vorerst drei oder vier Wochen.</small></div><div id="setupPeriodOptions">${periodOptions(p)}</div><div class="setup-fields"><label class="field-label" for="setupStart">Lernstart<input id="setupStart" type="date" value="${p.start}"></label><label class="field-label" for="setupMinutes">Zeit pro Lerntag<select id="setupMinutes">${[15,30,45,60,90].map(n=>`<option value="${n}" ${p.minutes===n?'selected':''}>${n} Minuten</option>`).join('')}</select></label><label class="field-label" for="setupSession">Größe einer Einheit<select id="setupSession">${[5,10,15,20].map(n=>`<option value="${n}" ${p.session===n?'selected':''}>${n} Fälle</option>`).join('')}</select></label><label class="field-label" for="setupReview">Abschlusswiederholung<select id="setupReview">${reviewOptions(p)}</select></label></div><label class="field-label">An welchen Tagen hast du Zeit?</label><div class="weekday-options">${weekdayButtons('setup-weekday',p.weekdays)}</div><div id="setupPlanPreview">${window.LernpassPlannerUI.preview({state:{...state,plan:p},cards,button,fmtDate,recommendAction:'setup-use-recommended',validate:true})}</div>`;
    if(step===1)body=`<div class="eyebrow">SCHRITT 2 · DEINE VORLIEBEN</div><h1>Was macht dir<br>den Einstieg <em>leichter?</em></h1><p class="setup-intro">Wähle eine oder zwei Formen, die dir liegen. Der Plan nutzt sie als Einstieg und lernt danach aus deinen tatsächlichen Antworten.</p><div class="format-options">${[['practice','settings','Praxisbeispiele','Ich verstehe Begriffe leichter mit einem Beispiel aus dem Betrieb.'],['structure','diagram','Klare Struktur','Ich möchte Zusammenhänge geordnet sehen und Bilder dazunehmen.'],['speak','talk','Laut erklären','Ich merke, was ich kann, wenn ich es jemandem erkläre.'],['compact','learn','Kurz & übersichtlich','Ich starte gerne mit kleinen Abschnitten und einem Merksatz.']].map(([key,i,t,text])=>button('setup-format',`<span class="format-icon">${icon(i)}</span><strong>${t}</strong><span>${text}</span><i>${p.formats.includes(key)?icon('check'):''}</i>`,'format-option '+(p.formats.includes(key)?'selected':''),`data-format="${key}" aria-pressed="${p.formats.includes(key)}"`)).join('')}</div><div class="subtle-note">Es gibt keine feste Lerntyp-Zuordnung. Erinnern, Verstehen und verteiltes Wiederholen bleiben die Basis – unabhängig von deinen Vorlieben.</div>`;
    if(step===2){const q=diagnostics[setup.quizIndex],choice=setup.choices[setup.quizIndex];body=`<div class="eyebrow">SCHRITT 3 · KURZER WISSENSCHECK</div><div class="diagnostic-top"><span class="tag ${categoryStyle(q.category)}">${q.category}</span><span>${setup.quizIndex+1} / ${diagnostics.length}</span></div><h1 class="quiz-question">${q.q}</h1><p class="setup-intro">Kein Prüfungsergebnis, nur ein Startpunkt. Wenn du es nicht weißt, überspringe die Frage.</p><div class="quiz-options">${q.options.map((a,n)=>button('quiz-choice',`<span>${String.fromCharCode(65+n)}</span><strong>${a}</strong>${choice===n?icon('check'):''}`,'quiz-option '+(choice===n?'selected':''),`data-choice="${n}" aria-pressed="${choice===n}"`)).join('')}</div>${choice!==null?`<div class="notice ${choice===q.correct?'positive':'neutral'}"><strong>${choice===q.correct?'Richtig eingeordnet.':'Hier lohnt sich ein früher Einstieg.'}</strong> ${q.why}</div>`:''}`;}
    if(step===3){const answered=setup.choices.filter(x=>x!==null).length,correct=setup.choices.filter((x,i)=>x===diagnostics[i].correct).length;const activeDays=Array.from({length:C.planInfo({plan:p}).days},(_,n)=>C.addDays(p.start,n)).filter(d=>p.weekdays.includes(C.weekday(d))).length,budget=activeDays*p.minutes,need=Math.round(cards.length*9);body=`<div class="eyebrow">SCHRITT 4 · DEIN STARTPUNKT</div><h1>Dein Weg steht.<br><em>Jetzt wird daraus Wissen.</em></h1><p class="setup-intro">${p.deadline?"Bis zu deiner Prüfung am "+fmtDate(p.deadline,true):p.days/7+" Wochen"}, kompakte Einheiten und Wiederholungen, die mit deinem Wissen mitwachsen.</p><div class="setup-summary"><div><span>DEIN ZEITRAUM</span><b>${C.planInfo({plan:p}).days} Tage</b><small>${p.deadline?"Prüfung "+fmtDate(p.deadline,true):"ab "+fmtDate(p.start,true)}</small></div><div><span>DEINE LERNZEIT</span><b>${p.minutes} Min.</b><small>an ${p.weekdays.length} Tagen pro Woche</small></div><div><span>DEIN WISSENSCHECK</span><b>${answered?correct+'/'+answered:'Offen'}</b><small>${answered?'richtig eingeordnet':'wir starten offen und passen an'}</small></div></div>${window.LernpassPlannerUI.preview({state:{...state,plan:p},cards,button,fmtDate})}<div class="personal-plan"><h2>So passt sich dein Lernpass an</h2><ul><li>${p.formats.map(f=>formatNames[f]).join(' + ')} als bevorzugter Einstieg.</li><li>Schwächere Themen aus dem Check kommen zuerst. Alle 94 Fälle bleiben im Plan.</li><li>Unsichere Antworten kommen früher zurück; sicher erinnerte später.</li><li>Vorwissen überspringt keine Lernstufen. Dein tatsächlicher Abruf zählt.</li></ul></div>${budget<need?`<div class="notice warning">Deine gewählte Zeit ist knapp: ${activeDays} Lerntage × ${p.minutes} Min. = ${budget} Min. Für den ersten Durchgang mit Wiederholungen sind grob ${need} Min. eingeplant. Vier Wochen oder mehr Zeit pro Lerntag geben dir mehr Spielraum.</div>`:'<div class="notice positive">Dein Zeitbudget bietet einen guten Rahmen. Wie viel du tatsächlich brauchst, zeigt sich beim Lernen.</div>'}<div class="subtle-note">Dein Lernstand wird lokal gespeichert und automatisch mit deinem angemeldeten Konto abgeglichen. Sicherungen bleiben zusätzlich möglich.</div>`;}
    return `<div class="setup-shell"><header><a class="brand" href="#"><span class="brand-mark">m<span>·</span></span><span>mechatronik<small>DEIN LERNPASS</small></span></a>${state.onboarded?button('setup-cancel',icon('close'),'icon-button','aria-label="Einrichtung abbrechen"'):'<span class="setup-time">Einmal einrichten · ca. 3 Minuten</span>'}</header><main id="main" tabindex="-1" class="setup-main"><nav class="setup-progress" aria-label="Einrichtungsschritte">${['Alltag','Vorlieben','Wissenscheck','Dein Plan'].map((n,i)=>`<span class="${i===step?'current':i<step?'finished':''}"><b>${i<step?icon('check'):i+1}</b><i>${n}</i></span>`).join('')}</nav><section class="setup-card panel">${body}<div class="setup-navigation">${step?button('setup-back',icon('back')+' Zurück','button secondary'):'<span></span>'}<div>${step===2?button('quiz-skip','Weiß ich noch nicht','link-button'):''}${button(step===3?'setup-finish':'setup-next',step===3?'Meinen Lernpass starten '+icon('arrow'):'Weiter '+icon('arrow'),'button primary',step===2&&setup.choices[setup.quizIndex]===null?'disabled':'')}</div></div></section></main><footer>94 Lernfälle · eigene Musterantworten · dein persönliches Tempo</footer></div>`;
  }
  function modal(title,html,wide=false){document.querySelector('dialog')?.close();const d=document.createElement('dialog');d.className='dialog'+(wide?' wide':'');d.innerHTML=`<header><h2>${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Schließen">${icon('close')}</button></header><div class="dialog-body">${html}</div>`;d.addEventListener('close',()=>{d.remove();if(route==='catalog'&&$('catalogResults'))$('catalogResults').innerHTML=catalogResults();});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});document.body.append(d);d.showModal();return d;}
  function openCard(id){const card=cards.find(c=>c.id===id);if(!card)return;const s=C.cardState(state,id);modal(card.id+' · '+card.title,`<div class="detail-intro"><span class="tag ${categoryStyle(card.category)}">${card.category}</span>${stageDots(s.stage)}<p>${esc(card.question)}</p></div>${Q.visualNote(card)}<div class="button-row">${button('worksheet-open','Diese Frage selbst ausfüllen','button primary',`data-id="${id}"`)}</div>${answerHTML(card)}${s.answerText?`<details class="own-answer-history"><summary>Deine gespeicherte Erklärung${s.answerCompleted?'':' · Entwurf'}</summary><p class="answer-verbatim">${esc(s.answerText)}</p><small>${s.answerDay?fmtDate(s.answerDay):''}</small></details>`:''}<label class="field-label" for="cardNote">Deine Notiz <span>wird automatisch lokal gespeichert</span></label><textarea id="cardNote" data-card="${id}" maxlength="2000" rows="3" placeholder="Dein Praxisbeispiel oder ein wichtiger Zusammenhang …">${esc(s.note)}</textarea><div class="button-row">${button('train-one','Diesen Fall lernen '+icon('arrow'),'button primary',`data-id="${id}"`)}${button('train-write','Frei beantworten','button secondary',`data-id="${id}"`)}${button('favorite',icon('star')+(s.favorite?' Gemerkt':' Merken'),'button secondary',`data-id="${id}"`)}</div>`,true);}
  function worksheetFeedback(){const e=Q.entry(state,worksheetId),status=$('worksheetStatus'),toggle=document.querySelector('[data-action="worksheet-complete"]');if(status)status.textContent=e.completed?'Ausgefüllt':Q.status(state,worksheetId)==='started'?'In Bearbeitung':'Noch offen';if(toggle){toggle.innerHTML=e.completed?icon('check')+' Ausgefüllt · wieder öffnen':'Als ausgefüllt markieren';toggle.className='button '+(e.completed?'secondary':'primary');}if($('workbookProgress'))$('workbookProgress').textContent=cards.filter(c=>Q.status(state,c.id)==='complete').length+' ausgefüllt · '+cards.filter(c=>Q.status(state,c.id)==='started').length+' begonnen · '+cards.filter(Q.isVisual).length+' Bild- / Skizzenfragen';}
  function catalogSelection(){return Q.selected(C.filter(cards,state,filters),state,filters);}
  function catalogResults(){const list=catalogSelection();if(!list.length)return '<div class="empty-state panel"><h2>Keine Fragen in dieser Auswahl.</h2><p>Ändere die Filter, um weitere Fragen zu sehen.</p></div>';if(catalogView==='overview')return Q.overview({state,cards:list,button,answerHTML,drawings:drawingLinks});if(catalogView==='fill'){if(!list.some(c=>c.id===worksheetId))worksheetId=list.find(c=>Q.status(state,c.id)!=='complete')?.id||list[0].id;return Q.editor({state,card:list.find(c=>c.id===worksheetId),list,button,icon,answerHTML,drawings:drawingLinks,uploading:Boolean(imageUpload)});}return cardsResults();}
  function knowledgeDialog(){const known=new Set(F.learnedIds(state,cards)),list=cards.filter(c=>known.has(c.id)),visual=list.filter(Q.isVisual).length;modal('Dein Wissen testen',`<p>Alle <strong>${list.length} bereits gelernten Fragen</strong> werden einmal zufällig gemischt. Keine neuen Fragen und keine übernommenen früheren Antworten. Du kannst jederzeit pausieren und später fortsetzen.</p><p>${list.length-visual} Textfragen · ${visual} Bild- / Skizzenfragen. Texte prüft Gemini; Abbildungen und Skizzen vergleichst und bewertest du selbst.</p><div class="button-row">${button('knowledge-start','Alle gelernten Fragen testen','button primary',`data-scope="all" ${list.length?'':'disabled'}`)}${button('knowledge-start','Nur gelernte Textfragen','button secondary',`data-scope="text" ${list.length-visual?'':'disabled'}`)}${button('knowledge-start','Nur gelernte Bildfragen','button secondary',`data-scope="visual" ${visual?'':'disabled'}`)}</div><p class="small-muted">Ein offener Wissenstest dieser Auswahl wird fortgesetzt. Reines Ausfüllen des Katalogs zählt nicht als gelernt.</p>`);}
  async function uploadWorksheetImages(input){
    const files=[...input.files],id=worksheetId,owner=state;if(!files.length)return;if(imageUpload){toast('Bitte den laufenden Bildupload abwarten.');return;}if(files.length>Q.MAX_IMAGES-Q.entry(state,id).images.length){toast('Pro Frage sind höchstens sechs Bilder möglich. Bitte weniger Dateien wählen.');input.value='';return;}
    imageUpload={id};input.disabled=true;let stored=0;
    try{for(const file of files){if(state!==owner)throw Error('Der Lernstand wurde gewechselt. Bitte die Frage erneut öffnen.');if($('worksheetUploadStatus'))$('worksheetUploadStatus').textContent=`Bild ${stored+1} von ${files.length} wird vorbereitet und gespeichert …`;const prepared=await Q.prepareImage(file);const r=await fetch('/api/worksheet-images',{method:'POST',credentials:'same-origin',headers:{'Content-Type':prepared.blob.type,'X-Case-Id':id,'X-Image-Name':encodeURIComponent(prepared.name)},body:prepared.blob,signal:AbortSignal.timeout(45000)});if(r.redirected||!r.headers.get('content-type')?.includes('application/json'))throw Error('Bitte erneut mit deinem ChatGPT-Konto anmelden.');const data=await r.json();if(!r.ok)throw Error(data.error||'Das Bild konnte nicht gespeichert werden.');if(state!==owner)throw Error('Der Lernstand wurde gewechselt. Bitte die Frage erneut öffnen.');Q.addImage(state,id,data);if(!save())throw Error('Das Bild ist hochgeladen, aber sein Verweis konnte nicht lokal gespeichert werden. Bitte vor dem Schließen ein Backup exportieren.');stored++;}}
    catch(e){toast((stored?stored+' Bild(er) gespeichert. ':'')+(e.message||'Die Bildspeicherung ist unterbrochen. Bitte erneut versuchen.'));}
    finally{imageUpload=null;if(state===owner&&route==='catalog'&&catalogView==='fill'&&worksheetId===id)render();if(stored===files.length)toast(stored===1?'Bild und Antwort gespeichert.':'Bilder und Antwort gespeichert.');}
  }
  async function exportWorkbook(){
    const snapshot=JSON.parse(JSON.stringify(state)),list=catalogSelection(),images=new Map();toast('Dein Katalog wird mit den eigenen Bildern zusammengestellt …');
    try{for(const card of list)for(const image of Q.entry(snapshot,card.id).images){if(images.has(image.id))continue;const r=await fetch(Q.imageUrl(image.id),{credentials:'same-origin',signal:AbortSignal.timeout(20000)});if(!r.ok||!r.headers.get('content-type')?.startsWith('image/'))throw Error('Ein Bild konnte nicht geladen werden. Bitte anmelden und den Download erneut versuchen.');const blob=await r.blob(),data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});images.set(image.id,data);}
      const html='<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'"><title>Mein Mechatronik-Fragenkatalog</title><style>body{max-width:900px;margin:40px auto;padding:20px;font:16px/1.7 system-ui;color:#183c34}article{border-top:1px solid #ccd9d4;padding:24px 0;break-inside:avoid}h1{font-size:30px}h2{font-size:21px}p{white-space:pre-wrap}img{max-width:100%;max-height:650px;object-fit:contain}small{color:#52675f}@media print{body{margin:0;padding:0}a{color:inherit}}</style><h1>Mein Mechatronik-Fragenkatalog</h1><p>'+list.length+' Fragen · eigene Antworten und Skizzen · '+C.today()+'</p>'+list.map(c=>{const e=Q.entry(snapshot,c.id);return '<article><small>'+c.id+' · '+Q.esc(c.category)+(Q.isVisual(c)?' · Bild-/Skizzenfrage · selbst vergleichen':'')+'</small><h2>'+Q.esc(c.title)+'</h2><p>'+Q.esc(c.question)+'</p><h3>Meine Antwort</h3><p>'+Q.esc(e.text||'Noch keine Textantwort.')+'</p>'+e.images.map(i=>'<figure><img src="'+images.get(i.id)+'" alt="'+Q.esc(i.caption||i.name)+'"><figcaption>'+Q.esc(i.caption||i.name)+'</figcaption></figure>').join('')+'<small>'+(e.completed?'Selbst als ausgefüllt markiert':'Noch in Bearbeitung')+'</small></article>';}).join('')+'</html>';
      const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Mein-Mechatronik-Fragenkatalog-'+C.today()+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Katalog mit Antworten und Bildern heruntergeladen. Die HTML-Datei lässt sich auch offline öffnen und drucken.');
    }catch(e){toast(e.message||'Der Katalog konnte nicht vollständig heruntergeladen werden.');}
  }
  function settings(){modal('Dein Lernraum',`<div class="settings-section"><h3>Lernprofil & Plan</h3><p>${state.plan.deadline?'Prüfung am '+fmtDate(state.plan.deadline):state.plan.days/7+' Wochen'} · ${state.plan.minutes} Minuten · bevorzugt ${state.plan.formats.map(f=>formatNames[f]).join(', ')}.</p>${button('profile','Profil und Einstiegscheck anpassen','button secondary')}${button('exam-plan','Prüfungstermin & Abschlusswiederholung','text-link')}</div><div class="settings-section"><h3>Geräte & Sicherungen</h3>${button("sync-settings","Synchronisierung und frühere Sicherungen","text-link")}<p>Deine eigenen Katalogantworten mit Bildverweisen, Lerneinheiten, Tests, Wiederholungsfragen, Erklärungen, Notizen und Favoriten werden lokal gespeichert und mit deinem angemeldeten Konto auf dem Server abgeglichen. Verwende auf Handy und PC dasselbe ChatGPT-Konto. Bei gleichzeitigen Änderungen fragt die App nach, bevor ein anderer Stand übernommen wird.</p><div class="button-row">${button('export',icon('download')+' Backup exportieren','button primary')}<label class="button secondary file-button">Backup importieren<input id="backupImport" type="file" accept="application/json,.json" aria-label="Lernpass-Backup importieren"></label></div><p class="small-muted">Das JSON-Backup enthält Bildverweise auf deinen privaten Online-Speicher. Für eine eigenständige Datei einschließlich Bildern nutze im Gesamtkatalog „Mit eigenen Antworten herunterladen“. Importieren ersetzt den lokalen Lernstand nach einer Bestätigung. Vorher kannst du deinen bisherigen Stand exportieren.</p></div><div class="settings-section"><h3>Eigene KI-Verbindung · optional</h3>${aiBadge()}${button('ai-settings','Eigenen API-Schlüssel verwalten','button secondary')}<p>Deine eigene Erklärung wird pro Fall lokal gespeichert. Beim Klick auf „Mit Gemini prüfen“ erhält Google nur die Antwort, die Frage und ihre Fachpunkte. Im Einzeltraining bestätigst du deinen Lernstand selbst. In Tests werden die Bewertungen automatisch in den Lernplan und den Wiederholungspool übernommen. Unklare Bewertungen erhöhen keine Lernstufe.</p><p>${ai.configured?'Gemini ist eingerichtet.':'Du kannst ohne KI selbst vergleichen oder deinen eigenen Gemini-API-Schlüssel verbinden.'}</p><a class="text-link" href="https://aistudio.google.com/api-keys" target="_blank" rel="noopener noreferrer">Google AI Studio öffnen ↗</a></div><div class="settings-section"><h3>Auf deinem Handy</h3><p>Öffne den Weblink in deinem Browser. Du kannst ihn über die Browserfunktion zum Home-Bildschirm hinzufügen. Mit demselben Konto kannst du deinen Lernstand auch auf anderen Geräten fortsetzen.</p></div><div class="settings-section"><h3>Inhalte & Quellen</h3><p>Version 1.6.1 · MEC H1 · 94 Fälle in D und E. Eigene Lernfragen und Erklärungen, kein offizieller Lösungsschlüssel. Die Originalzeichnungen sind beim jeweiligen Fall verlinkt.</p>${button('about','Lernmethode und Fachquellen ansehen','text-link')}</div>`);}
  let examDraft=null;
  function weekdayButtons(action,selected){return [[1,'Mo'],[2,'Di'],[3,'Mi'],[4,'Do'],[5,'Fr'],[6,'Sa'],[0,'So']].map(([n,t])=>button(action,t,'weekday '+(selected.includes(n)?'selected':''),`data-day="${n}" aria-label="${['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'][n]}" aria-pressed="${selected.includes(n)}"`)).join('');}
  function reviewOptions(p){return `<option value="auto" ${p.reviewAuto?'selected':''}>Automatisch</option>`+[2,3,5,7].map(n=>`<option value="${n}" ${!p.reviewAuto&&p.finalReviewDays===n?'selected':''}>${n} Kalendertage</option>`).join('');}
  function periodOptions(p){return p.deadline?`<div class="notice positive">Dein Prüfungstermin bestimmt die Länge des Plans. ${button('setup-clear-deadline','Ohne Prüfungstermin planen','text-link')}</div>`:`<label class="field-label">Dein vorläufiger Zeitraum</label><div class="duration-options">${[21,28].map(days=>button('setup-days',`<span>${days/7} Wochen</span><b>${days} Tage</b><small>${days===21?'Kompakt & fokussiert':'Mehr Raum zum Wiederholen'}</small>`,'duration-option '+(p.days===days?'selected':''),`data-days="${days}" aria-pressed="${p.days===days}"`)).join('')}</div>`;}
  function setupPlanPreview(){if(!setup||!$('setupPlanPreview'))return;$('setupPeriodOptions').innerHTML=periodOptions(setup.plan);$('setupPlanPreview').innerHTML=window.LernpassPlannerUI.preview({state:{...state,plan:setup.plan},cards,button,fmtDate,recommendAction:'setup-use-recommended',validate:true});}
  function examPlan(){examDraft=JSON.parse(JSON.stringify(state.plan));if(!examDraft.deadline)examDraft.reviewAuto=true;const p=examDraft;modal('Dein Prüfungstermin. Dein Lernplan.',`<p>Dein echter Prüfungstermin bestimmt die Länge des Plans. Deine Lerntage, Zeit und bisherigen Antworten bestimmen, wie du den Stoff angehst.</p><div class="exam-layout"><div class="exam-fields"><div class="exam-input-grid"><label class="field-label" for="examDeadline">Prüfungstermin<input id="examDeadline" type="date" min="${C.addDays(C.today(),1)}" max="${C.addDays(p.start,366)}" value="${p.deadline||''}"></label><label class="field-label" for="examStart">Lernstart<input id="examStart" type="date" value="${p.start}"></label><label class="field-label" for="examMinutes">Zeit pro Lerntag<select id="examMinutes">${[15,30,45,60,90].map(n=>`<option value="${n}" ${p.minutes===n?'selected':''}>${n} Minuten</option>`).join('')}</select></label><label class="field-label" for="examReview">Abschlusswiederholung<select id="examReview">${reviewOptions(p)}</select></label></div><label class="field-label">Deine verfügbaren Lerntage</label><div id="examWeekdays" class="weekday-options">${weekdayButtons('exam-weekday',p.weekdays)}</div><p class="small-muted">Der Prüfungstag selbst bleibt frei. Ohne Datum gilt dein gewählter 3- oder 4-Wochen-Rahmen. Änderungen werden erst beim Speichern übernommen.</p></div><div id="examPreview">${window.LernpassPlannerUI.preview({state:{...state,plan:p},cards,button,fmtDate,recommendAction:'exam-use-recommended',validate:true})}</div></div><div class="button-row exam-save">${button('save-exam-plan','Persönlichen Lernplan erstellen','button primary')}${button('close-dialog','Abbrechen','button secondary')}</div>`,true);}
  function readExamDraft(){if(!examDraft||!$('examDeadline'))return null;return {...examDraft,start:$('examStart').value,deadline:$('examDeadline').value||null,minutes:Number($('examMinutes').value),reviewAuto:$('examReview').value==='auto',finalReviewDays:$('examReview').value==='auto'?examDraft.finalReviewDays:Number($('examReview').value)};}
  function examPreview(){const p=readExamDraft();if(!p)return;$('examPreview').innerHTML=window.LernpassPlannerUI.preview({state:{...state,plan:p},cards,button,fmtDate,recommendAction:'exam-use-recommended',validate:true});if(C.validDate(p.start))$('examDeadline').max=C.addDays(p.start,366);}
  function saveExamPlan(){const p=readExamDraft();if(!p)return;const error=C.validatePlan(p);if(error){toast(error);return;}state.plan=C.normalize({...state,plan:p},cards).plan;save();examDraft=null;document.querySelector('dialog')?.close();render();toast('Dein persönlicher Lernplan ist erstellt und wird laufend angepasst.');}
  function syncLabels(){const s=syncController?.getStatus()||{phase:'offline',message:'Diese Datei arbeitet lokal. Öffne den Online-Link für den Geräteabgleich.'};const names={checking:'Abgleichen …',syncing:'Übertragen …',pending:'Lokal gespeichert',synced:'Synchronisiert',conflict:'Abgleich nötig',waiting:'Neuer Lernstand',offline:'Lokal · offline',login:'Anmelden'};return {...s,label:names[s.phase]||'Abgleich',short:s.phase==='synced'?'Online':s.phase==='offline'?'Lokal':s.phase==='conflict'?'Prüfen':'Abgleich'};}
  function syncBadge(){const s=syncLabels();return `<button id="syncIndicator" type="button" data-action="sync-settings" class="sync-indicator ${s.phase}" aria-label="Synchronisierung: ${esc(s.label)}"><i></i><span class="sync-full">${esc(s.label)}</span><span class="sync-short">${esc(s.short)}</span></button>`;}
  function snapshotSummary(s){if(!s)return 'Noch kein Stand vorhanden';const questions=Object.values(s.cards||{}).filter(c=>c.reps>0).length,tests=s.learning?.tests?.length||0,notes=Object.values(s.cards||{}).filter(c=>c.note).length;return `${questions} ${questions===1?'Frage':'Fragen'} geübt · ${tests} ${tests===1?'Test':'Tests'} · ${notes} ${notes===1?'Notiz':'Notizen'}`;}
  function syncDiffs(local,remote){
    if(!remote)return '';const changes=[];
    const add=(label,a,b)=>{if(a!==b)changes.push({label,a:String(a||'Leer'),b:String(b||'Leer')});};
    add('Prüfungstermin',local.plan.deadline,remote.plan.deadline);add('Lernzeit pro Tag',local.plan.minutes,remote.plan.minutes);add('Abschlusswiederholung',local.plan.finalReviewDays,remote.plan.finalReviewDays);
    for(const card of cards){add(card.id+' · Eigene Katalogantwort',Q.entry(local,card.id).text,Q.entry(remote,card.id).text);add(card.id+' · Eigene Bilder',Q.entry(local,card.id).images.map(i=>i.id+' '+i.caption).join(', '),Q.entry(remote,card.id).images.map(i=>i.id+' '+i.caption).join(', '));add(card.id+' · Notiz',local.cards[card.id]?.note||'',remote.cards[card.id]?.note||'');add(card.id+' · Eigene Erklärung',local.cards[card.id]?.answerText||'',remote.cards[card.id]?.answerText||'');}
    const tests=new Map((remote.learning?.tests||[]).map(t=>[t.id,t]));
    for(const t of local.learning.tests){const other=tests.get(t.id);if(other)for(const id of t.ids)if(other.entries[id])add(id+' · Testantwort',t.entries[id].answer,other.entries[id].answer);}
    return `<details class="sync-differences"><summary>Unterschiede ansehen${changes.length?' · '+changes.length:''}</summary>${changes.length?changes.slice(0,4).map(c=>`<article><strong>${esc(c.label)}</strong><small>Auf diesem Gerät</small><p>${esc(c.a.slice(0,450))}${c.a.length>450?' …':''}</p><small>Auf dem Server</small><p>${esc(c.b.slice(0,450))}${c.b.length>450?' …':''}</p></article>`).join(''):'<p>Die Stände unterscheiden sich im Übungsfortschritt, bei Einheiten oder Bewertungen.</p>'}<p class="small-muted">Auszug zur Orientierung. Du kannst beide vollständigen Stände einzeln als Backup exportieren.</p>${button('sync-conflict-backup','Aktuellen Serverstand exportieren','text-link')}</details>`;
  }
  function syncContents(){const s=syncLabels(),conflict=syncController?.getConflict();return `<div class="sync-message ${s.phase}"><strong>${esc(s.label)}</strong><p>${esc(s.message)}</p>${s.lastAt?`<small>Letzter Abgleich: ${new Date(s.lastAt).toLocaleString('de-AT')}</small>`:''}</div><p>Öffne die App auf Handy und PC mit demselben ChatGPT-Konto. Änderungen werden automatisch übertragen; ohne Verbindung kannst du lokal weiterlernen.</p>${conflict&&!conflict.waiting?`<div class="sync-comparison"><div><b>Auf diesem Gerät</b><p>${snapshotSummary(state)}</p></div><div><b>Auf dem Server</b><p>${snapshotSummary(conflict.state)}</p></div></div>${syncDiffs(state,conflict.state)}<p>Wähle den Stand, mit dem du weiterlernen möchtest. Die andere Fassung wird vor der Übernahme gesichert. Antworten und Notizen werden bei Konflikten nicht still zusammengeführt.</p><div class="button-row">${button('sync-server','Serverstand übernehmen','button primary',conflict.state?'':'disabled')}${button('sync-local','Diesen Stand übertragen','button secondary')}</div>`:`<div class="button-row">${button('sync-now','Jetzt abgleichen','button primary')}</div>`}<hr><h3>Sicherungen mitnehmen</h3><p>Du kannst vor einer Auswahl den aktuellen Stand exportieren. Zusätzlich sind die letzte Browser-Sicherung und bis zu drei vorherige Serverstände verfügbar. Der Download lädt jeweils die neueste frühere Sicherung.</p><div class="button-row">${button('export','Aktuellen Stand exportieren','button secondary')}${button('sync-browser-backup','Frühere Browser-Sicherung','text-link')}${button('sync-server-backup','Frühere Server-Sicherung','text-link')}</div>`;}
  function syncDialog(){modal('Deine Geräte. Ein Lernstand.',`<div id="syncDetails">${syncContents()}</div>`);}
  let lastSyncBadge='',lastSyncDetails='';
  function updateSyncStatus(){const indicator=$('syncIndicator'),badge=syncBadge();if(indicator&&lastSyncBadge!==badge){indicator.outerHTML=badge;lastSyncBadge=badge;}const details=$('syncDetails'),content=details?syncContents():'';if(details&&lastSyncDetails!==content){const wasOpen=details.querySelector('.sync-differences')?.open;details.innerHTML=content;if(wasOpen&&details.querySelector('.sync-differences'))details.querySelector('.sync-differences').open=true;lastSyncDetails=content;}}
  async function downloadServerBackup(){try{const backup=await syncController?.serverBackup();if(backup)downloadState(backup,'Server-Sicherung');else toast('Es ist noch keine frühere Server-Sicherung vorhanden.');}catch(e){toast(e.message||'Die Sicherung konnte nicht geladen werden.');}}
  function about(){modal('Quellen & Lernmethode',`<p>Die 94 Fälle sind den Nummern D1–D46 und E1–E48 des verlinkten WKO-Katalogs (02/2024, MEC H1 V1.7) zugeordnet. Fragen und Erklärungen sind eigenständig formuliert. Originalzeichnungen werden verlinkt, nicht in die App kopiert.</p>${sourceLink(1,'Originalkatalog öffnen')}<h3>Was der Lernpass berücksichtigt</h3><p>Vorwissen aus einem kurzen Check, verfügbare Lerntage, Zeitbudget, bevorzugte Übungsformen und vor allem deine tatsächlichen Bewertungen. Vorlieben sind keine wissenschaftlich gesicherten festen Lerntypen. Wir verbinden selbstständiges Erinnern mit zeitlich verteilten Wiederholungen.</p><a class="text-link" target="_blank" rel="noopener noreferrer" href="https://pubmed.ncbi.nlm.nih.gov/26162104/">Pashler et al.: Learning Styles – Concepts and Evidence ↗</a><a class="text-link" target="_blank" rel="noopener noreferrer" href="https://pubmed.ncbi.nlm.nih.gov/16507066/">Roediger & Karpicke: Test-enhanced learning ↗</a><h3>Wie die Stufen funktionieren</h3><p>Gewusst erhöht die Stufe höchstens einmal pro Tag. Unsicher verkürzt den Abstand; Nochmal plant eine Wiederholung für heute. Fünf Stufen entstehen aus wiederholtem Abruf an unterschiedlichen Tagen. Der Check vergibt keine Stufen. Deine Einschätzung ersetzt keine fachliche Prüfung.</p><h3>Fachliche Einordnung</h3><p>Hersteller- und Institutionsquellen findest du direkt unter jeder Musterantwort. Normenstände und Betriebsunterlagen müssen für die konkrete Anlage geprüft werden. Praktische Arbeiten an elektrischen Anlagen, Robotern oder gespeicherter Energie gehören in fachkundige Hände. Die Texte dienen der Prüfungsvorbereitung.</p>`,true);}
  function start(mode='mixed',ids){document.querySelector('dialog')?.close();if(mode==='mixed'&&state.plan.formats.includes('speak'))mode='speak';let list=ids?ids.map(id=>cards.find(c=>c.id===id)).filter(Boolean):mode==='exam'?[...cards].sort(()=>Math.random()-.5).slice(0,5):C.dailyQueue(cards,state,C.today(),['speak','write'].includes(mode)?'mixed':mode);if(!list.length&&['speak','write'].includes(mode))list=[...cards].sort((a,b)=>C.cardState(state,a.id).stage-C.cardState(state,b.id).stage);if(!list.length){toast(mode==='weak'?'Noch keine als unsicher bewerteten Fälle. Starte mit deinem Tagesmix.':'Für diese Auswahl gibt es gerade keine offenen Fälle.');return;}session={mode,ids:list.slice(0,mode==='exam'?5:state.plan.session).map(c=>c.id),position:0,revealed:false,submitted:false,checking:false,assessment:null,checkError:'',results:[],scratch:mode==='write'?(C.cardState(state,list[0].id).answerText||''):'',started:Date.now(),cardStarted:Date.now(),done:false,retries:{},savedExam:false};go('learn');}
  function finish(){if(!session)return;session.done=true;if(session.mode==='exam'&&!session.savedExam&&session.results.length){state.exams.push({day:C.today(),total:session.results.length,good:session.results.filter(r=>r.grade==='good').length});state.exams=state.exams.slice(-100);session.savedExam=true;save();}render();}
  function render(){if(booting){$('app').innerHTML='<main class="loading-screen"><div class="brand-mark">m<span>·</span></div><p>Dein Lernstand wird abgeglichen …</p><button type="button" class="text-link" data-action="continue-local">Lokal weiterlernen</button></main>';return;}if(setup||!state.onboarded){$('app').innerHTML=setupPage();return;}$('app').innerHTML=shell(route==='catalog'?catalogPage():route==='pass'?passPage():route==='learn'?learnPage():home());}
  function downloadState(value,label='Backup'){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Mechatronik-Lernpass-'+label+'-'+C.today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup erstellt. Bewahre die Datei an einem sicheren Ort auf.');}
  function exportBackup(){downloadState(state);}
  let personalAiBusy=false;
  function aiBadge(){const phase=ai.connectionStatus||'unconfigured',connected=ai.configured&&phase==='connected',failed=['invalid','error'].includes(phase),label=connected?'KI verbunden':failed?'KI Fehler':'KI aus';return `<button type="button" data-ai-indicator="true" data-action="ai-settings" class="ai-indicator ${connected?'connected':failed?'failed':'off'}" aria-label="KI-Verbindung: ${label}"><i aria-hidden="true"></i><span>${label}</span></button>`;}
  function updateAiBadge(){for(const el of document.querySelectorAll('[data-ai-indicator]'))el.outerHTML=aiBadge();}
  function aiPanel(status=ai.connectionStatus,message=ai.message){const connected=status==='connected',failed=['invalid','error'].includes(status);return `<div class="personal-ai-state ${connected?'connected':failed?'failed':'off'}" role="status"><span class="ai-state-light" aria-hidden="true"></span><div><strong>${connected?'Verbunden':failed?'Verbindung prüfen':'Ohne KI nutzbar'}</strong><p>${esc(message||'Dein eigener API-Schlüssel ist freiwillig. Lernen, Skizzen und eigene Einschätzungen funktionieren auch ohne KI.')}</p></div></div>`;}
  function personalAiDialog(){modal('Deine KI. Dein Schlüssel.',`<div id="personalAiStatus">${aiPanel()}</div><p>Optional: Verbinde deinen eigenen Google-Gemini-Zugang für automatische Textbewertungen. Katalog, eigene Antworten, Bilder, Lernplan und Selbstvergleich bleiben auch ohne API nutzbar.</p><label class="field-label" for="personalAiModel">Modell<select id="personalAiModel">${[['gemini-3.1-flash-lite','Gemini 3.1 Flash-Lite'],['gemini-2.5-flash-lite','Gemini 2.5 Flash-Lite']].map(([v,l])=>`<option value="${v}" ${ai.model===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field-label" for="personalApiKey">Dein API-Schlüssel<span>${ai.hasKey?'Ein Schlüssel ist gespeichert. Zum Ersetzen einen neuen eingeben.':'Der Schlüssel wird nur für dein angemeldetes Konto gespeichert.'}</span></label><input id="personalApiKey" type="password" autocomplete="off" spellcheck="false" autocapitalize="off" maxlength="4096" placeholder="Vollständigen Schlüssel hier einfügen" aria-describedby="personalAiPrivacy"><p id="personalAiPrivacy" class="small-muted">Verschlüsselt auf dem Server gespeichert, getrennt vom Lernstand. Kein Schlüssel im Browser-Backup oder Katalog-Download. Der Verbindungscheck sendet den Schlüssel im Header direkt vom Server an Google.</p><div class="button-row personal-ai-actions">${button('ai-save','Prüfen & für mich speichern','button primary')}${ai.hasKey?button('ai-recheck','Verbindung erneut prüfen','button secondary'):''}${ai.hasKey?button('ai-disconnect','KI trennen & Schlüssel entfernen','text-link'):''}</div><p class="small-muted">Es gelten das Kontingent und die Abrechnung deines Google-Zugangs. Die App aktiviert keine kostenpflichtige Abrechnung. Bilder und Skizzen werden nicht an die KI gesendet.</p><a class="text-link" href="https://aistudio.google.com/api-keys" target="_blank" rel="noopener noreferrer">API-Schlüssel in Google AI Studio erstellen ↗</a>`);}
  function setAiBusy(busy){personalAiBusy=busy;document.querySelectorAll('.personal-ai-actions button').forEach(b=>b.disabled=busy);if($('personalApiKey'))$('personalApiKey').disabled=busy;}
  async function personalAiRequest(method,path,body){if(location.protocol==='file:')throw Error('Für eine persönliche KI-Verbindung bitte die Online-App öffnen. Der Katalog funktioniert hier ohne API.');const r=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(25000)});if(r.redirected||!r.headers.get('content-type')?.includes('application/json'))throw Error('Bitte erneut mit deinem ChatGPT-Konto anmelden.');const data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'Die Verbindung konnte nicht geprüft werden.'),{phase:data.connectionStatus||'error',previousConfigured:data.previousConfigured});return data;}
  async function savePersonalAi(){if(personalAiBusy)return;const input=$('personalApiKey'),key=input?.value.trim()||'',model=$('personalAiModel')?.value;if(key.length<20||key.length>4096||!/^[\x21-\x7e]+$/.test(key)||/["'`]/.test(key)){$('personalAiStatus').innerHTML=aiPanel('invalid','Bitte nur den vollständigen Schlüssel ohne Leerzeichen oder Zusatztext einfügen.');if(!ai.hasKey){ai.connectionStatus='invalid';ai.message='Bitte den vollständigen API-Schlüssel eingeben.';updateAiBadge();}return;}setAiBusy(true);$('personalAiStatus').innerHTML=aiPanel('loading','Schlüssel und Modellzugang werden geprüft …');try{const data=await personalAiRequest('PUT','/api/ai/profile',{key,model});ai={...ai,...data};updateAiBadge();if(input)input.value='';personalAiDialog();toast('Deine persönliche KI-Verbindung ist gespeichert.');}catch(e){if(input)input.value='';if(!ai.hasKey){ai.connectionStatus=e.phase||'error';ai.message=e.message;updateAiBadge();}if($('personalAiStatus'))$('personalAiStatus').innerHTML=aiPanel(e.phase||'error',(e.message||'Die Verbindung ist unterbrochen.')+(e.previousConfigured?' Dein bisher funktionierender Schlüssel bleibt gespeichert.':''));}finally{setAiBusy(false);}}
  async function checkPersonalAi(){if(personalAiBusy)return;setAiBusy(true);if($('personalAiStatus'))$('personalAiStatus').innerHTML=aiPanel('loading','Verbindung wird geprüft …');try{const data=await personalAiRequest('POST','/api/ai/profile/check');ai={...ai,...data};updateAiBadge();personalAiDialog();}catch(e){if($('personalAiStatus'))$('personalAiStatus').innerHTML=aiPanel('error',e.message);}finally{setAiBusy(false);}}
  async function disconnectPersonalAi(){if(personalAiBusy)return;setAiBusy(true);try{const data=await personalAiRequest('DELETE','/api/ai/profile');ai={...ai,...data};updateAiBadge();personalAiDialog();toast('KI getrennt. Dein Lernstand bleibt erhalten.');}catch(e){if($('personalAiStatus'))$('personalAiStatus').innerHTML=aiPanel('error',e.message);}finally{setAiBusy(false);}}
  let pendingImport=null;
  async function importBackup(file){if(!file)return;if(file.size>5*1024*1024){toast('Das Backup ist zu groß. Maximal 5 MB.');return;}try{pendingImport=C.normalize(JSON.parse(await file.text()),cards);modal('Lernstand importieren',`<p>Dieses Backup enthält ${Object.keys(pendingImport.cards).length} bearbeitete oder gemerkte Fälle. Es ersetzt den aktuellen Lernstand in diesem Browser.</p><div class="button-row">${button('confirm-import','Backup übernehmen','button primary')}${button('close-dialog','Abbrechen','button secondary')}</div>`);}catch{toast('Die Datei ist kein gültiges Lernpass-Backup. Dein aktueller Stand bleibt erhalten.');}}
  document.addEventListener('click',e=>{const link=e.target.closest('[data-route]');if(link){e.preventDefault();go(link.dataset.route);return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
    if(a==='ai-settings'){personalAiDialog();return;}if(a==='ai-save'){savePersonalAi();return;}if(a==='ai-recheck'){checkPersonalAi();return;}if(a==='ai-disconnect'){disconnectPersonalAi();return;}
    if(a==='overview-fold'){const list=[...document.querySelectorAll('.overview-reference')],open=list.some(d=>!d.open);for(const d of list)d.open=open;b.textContent=open?'Erklärungen zuklappen':'Erklärungen einblenden';return;}
    if(a==='answer-depth'){detailMode=b.dataset.depth==='summary'?'summary':'detailed';try{localStorage.setItem('mec-answer-depth',detailMode);}catch{}for(const box of document.querySelectorAll('.answer-explanation')){const card=cards.find(c=>c.id===box.dataset.answerId);if(card)box.innerHTML=X.switchHTML(detailMode)+'<div class="answer-explanation-body">'+answerBody(card)+'</div>';}for(const bar of document.querySelectorAll('.global-detail-switch'))bar.outerHTML=X.switchHTML(detailMode,true);if(catalogView==='overview'){for(const d of document.querySelectorAll('.overview-reference'))d.open=true;const fold=document.querySelector('[data-action="overview-fold"]');if(fold)fold.textContent='Erklärungen zuklappen';}return;}
    if(a==='catalog-view'){document.querySelector('dialog')?.close();catalogView=['cards','overview','fill'].includes(b.dataset.view)?b.dataset.view:'cards';go('catalog');return;}
    if(a==='worksheet-open'){document.querySelector('dialog')?.close();worksheetId=id;catalogView='fill';go('catalog');return;}
    if(a==='worksheet-prev'||a==='worksheet-next'){const list=catalogSelection(),p=list.findIndex(c=>c.id===worksheetId);worksheetId=list[p+(a==='worksheet-next'?1:-1)]?.id||worksheetId;render();window.scrollTo(0,0);return;}
    if(a==='worksheet-complete'){try{Q.complete(state,worksheetId);save();render();}catch(e){toast(e.message);}return;}
    if(a==='worksheet-copy-answer'){Q.setText(state,worksheetId,C.cardState(state,worksheetId).answerText||'');save();render();return;}
    if(a==='worksheet-remove-image'){const e=Q.edit(state,worksheetId);e.images=e.images.filter(i=>i.id!==b.dataset.image);e.completed=false;save();render();toast('Bild aus der Antwort entfernt. Frühere Sicherungen behalten ihren Verweis.');return;}
    if(a==='workbook-export'){exportWorkbook();return;}if(a==='workbook-print'){const opened=[...document.querySelectorAll('.overview-own')].map(d=>[d,d.open]);for(const[d]of opened)d.open=true;window.addEventListener('afterprint',()=>{for(const[d,o]of opened)d.open=o;},{once:true});window.print();return;}
    if(a==='knowledge-test'){knowledgeDialog();return;}if(a==='knowledge-start'){document.querySelector('dialog')?.close();try{openTest(F.createKnowledgeTest(state,cards,{scope:b.dataset.scope||'all'}).id);}catch(e){toast(e.message);}return;}
    if(a==='visual-catalog'){filters.visual='visual';catalogView='cards';go('catalog');return;}
    if(a==='self-grade'){const t=visibleTest(),card=cards.find(c=>c.id===id);if(!t||t.status==='draft'||!card||(!Q.isVisual(card)&&ai.configured)||grading)return;try{if(F.applyAssessment(state,t.id,card,F.selfAssessment(card,b.dataset.grade,Q.isVisual(card)))){C.review(state,id,b.dataset.grade);save();render();}}catch(e){toast(e.message);}return;}
    if(a==='continue-local'){booting=false;render();return;}
    if(a==='flow-hub'){flowView=null;session=null;go('learn');return;}
    if(a==='unit-start')return newUnit();
    if(a==='start'){const t=F.test(state,state.learning.activeTestId),u=F.unit(state,state.learning.activeUnitId);if(t&&t.status!=='complete')openTest(t.id);else if(u&&(!u.completed||!state.learning.tests.some(t=>t.unitId===u.id)))openUnit(u.id);else newUnit();return;}
    if(a==='unit-resume')return openUnit(id);
    if(a==='unit-reread'){const u=F.unit(state,id);if(u)u.position=0;return openUnit(id,true);}
    if(a==='unit-test')return newTest(id);
    if(a==='repeat-test')return newTest(null);
    if(a==='quick-test')return quickTest();
    if(a==='insight-card')return newUnit([id]);
    if(a==='insight-topic')return newUnit(window.LernpassInsights.topicSelection(state,cards,b.dataset.category,state.plan.session));
    if(a==='pool-learn')return newUnit(F.shuffle(Object.keys(state.learning.pool)).slice(0,state.plan.session));
    if(a==='test-open')return openTest(id);
    if(a==='exam'){const u=F.unit(state,state.learning.activeUnitId);if(u?.completed)newTest(u.id);else if(u)openUnit(u.id);else newUnit();return;}
    if(a==='train-one')return newUnit([id]);
    if(a==='train-filter')return newUnit(C.filter(cards,state,filters).slice(0,state.plan.session).map(c=>c.id));
    if(['unit-position','unit-prev','unit-studied'].includes(a)){const u=flowView?.type==='unit'?F.unit(state,flowView.id):null;if(!u)return;if(a==='unit-position'){const p=Number(b.dataset.position);if(Number.isInteger(p)&&p>=0&&p<u.ids.length)u.position=p;}if(a==='unit-prev')u.position=Math.max(0,u.position-1);if(a==='unit-studied'){F.markStudied(state,u.id,u.ids[u.position]);if(u.completed)flowView.reread=false;else{u.position=u.position<u.ids.length-1?u.position+1:u.ids.findIndex(q=>!u.studied.includes(q));}}save();render();window.scrollTo(0,0);return;}
    if(['test-position','test-prev','test-next'].includes(a)){const t=visibleTest();if(!t||t.status!=='draft')return;const p=a==='test-position'?Number(b.dataset.position):t.position+(a==='test-prev'?-1:1);if(Number.isInteger(p)&&p>=0&&p<t.ids.length)t.position=p;save();render();window.scrollTo(0,0);return;}
    if(a==='test-submit')return askTestSubmit();
    if(a==='test-confirm-submit'){const t=visibleTest();if(!t||t.status!=='draft')return;document.querySelector('dialog')?.close();F.submit(state,t.id);save();render();gradeTest(t.id);return;}
    if(a==='test-grade'){const t=visibleTest();if(t)gradeTest(t.id);return;}
    if(['home','learn','catalog','pass'].includes(a))return go(a);
    if(a==='exam-plan')return examPlan();if(a==='save-exam-plan')return saveExamPlan();if(a==='sync-settings')return syncDialog();if(a==='sync-now'){document.querySelector('dialog')?.close();syncController?.refresh();return;}if(a==='sync-conflict-backup'){const snapshot=syncController?.getConflict()?.state;if(snapshot)downloadState(snapshot,'Serverstand');return;}if(a==='sync-local'||a==='sync-server'){if(grading||session?.checking){toast('Bitte zuerst die laufende Bewertung abwarten.');return;}document.querySelector('dialog')?.close();syncController?.resolve(a==='sync-local'?'local':'server');return;}if(a==='sync-browser-backup'){const backup=syncController?.browserBackup();if(backup)downloadState(backup,'Browser-Sicherung');else toast('Es ist noch keine frühere Browser-Sicherung vorhanden.');return;}if(a==='sync-server-backup'){downloadServerBackup();return;}if(a==='settings')return settings();if(a==='about')return about();if(a==='profile')return openSetup();if(a==='close-dialog')return document.querySelector('dialog')?.close();
    if(a==='export')return exportBackup();if(a==='print')return window.print();
    if(a==='confirm-import'){if(pendingImport){state=pendingImport;pendingImport=null;setup=null;session=null;flowView=null;save();document.querySelector('dialog')?.close();go('home');toast('Dein Lernstand wurde übernommen.');}return;}
    if(a==='start-write')return start('write');if(a==='train-write')return start('write',[id]);if(a==='check-answer')return checkAnswer();if(a==='submit-answer'){if(!session||session.mode!=='write'||session.checking)return;try{C.saveAnswer(state,session.ids[session.position],session.scratch||'',true);save();session.submitted=true;render();}catch(e){toast(e.message);}return;}if(a==='edit-answer'){if(!session||session.checking)return;session.submitted=false;session.revealed=false;session.assessment=null;session.checkError='';render();$('scratchAnswer')?.focus();return;}if(a==='start')return start();if(a==='due')return start('due');if(a==='weak')return start('weak');if(a==='start-speak')return start('speak');if(a==='exam')return start('exam');
    if(a==='topic'){filters.category=b.dataset.category;filters.search='';go('catalog');return;}
    if(a==='filter-category'){filters.category=b.dataset.category;render();return;}
    if(a==='open-card')return openCard(id);if(a==='train-one')return start('mixed',[id]);if(a==='train-filter')return start('mixed',C.filter(cards,state,filters).map(c=>c.id));
    if(a==='favorite'){if(!cards.some(c=>c.id===id))return;state.cards[id]={...C.cardState(state,id),favorite:!C.cardState(state,id).favorite};save();if(document.querySelector('dialog')){b.innerHTML=icon('star')+(state.cards[id].favorite?' Gemerkt':' Merken');b.setAttribute('aria-pressed',String(state.cards[id].favorite));}else if(route==='catalog')$('catalogResults').innerHTML=catalogResults();else render();return;}
    if(a==='reveal'){if(session){session.revealed=true;render();document.querySelector('.answer-content')?.scrollIntoView({behavior:'smooth',block:'start'});}return;}
    if(a==='grade'){if(!session||session.checking||!(session.revealed||session.mode==='write'&&session.submitted)||session.done)return;const grade=b.dataset.grade,cardId=session.ids[session.position];if(session.mode!=='exam'){C.review(state,cardId,grade);save();}session.results.push({id:cardId,grade});if(grade==='again'&&session.mode!=='exam'&&(session.retries[cardId]||0)<1){session.ids.push(cardId);session.retries[cardId]=(session.retries[cardId]||0)+1;}session.position++;session.cardStarted=Date.now();session.revealed=false;session.submitted=false;session.assessment=null;session.checkError='';session.scratch=session.mode==='write'?(C.cardState(state,session.ids[session.position]).answerText||''):'';if(session.position>=session.ids.length)finish();else{render();window.scrollTo(0,0);}return;}
    if(a==='end-session')return finish();if(a==='session-home'){session=null;go('home');return;}if(a==='another'){session=null;newUnit();return;}
    if(a==='day'){const date=b.dataset.day,learned=new Set(state.history.filter(h=>h.day===date).map(h=>h.id));modal('Dein Plan · '+fmtDate(date),`<p><strong>${learned.size} Fälle bearbeitet.</strong> ${state.plan.weekdays.includes(C.weekday(date))?'Ein eingeplanter Lerntag.':'Ein freier Tag in deinem Wochenplan.'}</p><p>Dein Tagesmix wird am jeweiligen Tag aus fälligen Wiederholungen, deinem Vorwissen und noch neuen Fällen berechnet. Vergessene Antworten rücken nach vorne; spätere Bewertungen können Termine verändern.</p>${learned.size?`<div class="day-topics">${[...learned].map(id=>`<span class="tag">${id} · ${esc(cards.find(c=>c.id===id)?.title||'')}</span>`).join('')}</div>`:''}`);return;}
    if(a==='exam-weekday'){const day=Number(b.dataset.day);if(examDraft.weekdays.includes(day)){if(examDraft.weekdays.length===1){toast('Bitte mindestens einen Lerntag auswählen.');return;}examDraft.weekdays=examDraft.weekdays.filter(d=>d!==day);}else examDraft.weekdays.push(day);$('examWeekdays').innerHTML=weekdayButtons('exam-weekday',examDraft.weekdays);examPreview();return;}
    if(a==='exam-use-recommended'){const minutes=Number(b.dataset.minutes);if([15,30,45,60,90].includes(minutes)){$('examMinutes').value=String(minutes);examPreview();}return;}
    if(a==='setup-use-recommended'){const minutes=Number(b.dataset.minutes);if(setup&&[15,30,45,60,90].includes(minutes)){setup.plan.minutes=minutes;$('setupMinutes').value=String(minutes);setupPlanPreview();}return;}
    if(a==='setup-clear-deadline'){setup.plan.deadline=null;render();return;}
    if(a==='setup-days'){setup.plan.days=Number(b.dataset.days);render();return;}
    if(a==='setup-weekday'){const day=Number(b.dataset.day),set=setup.plan.weekdays;if(set.includes(day)){if(set.length===1){toast('Bitte mindestens einen Lerntag auswählen.');return;}setup.plan.weekdays=set.filter(d=>d!==day);}else set.push(day);render();return;}
    if(a==='setup-format'){const f=b.dataset.format,set=setup.plan.formats;if(set.includes(f)){if(set.length===1){toast('Bitte mindestens eine Übungsform auswählen.');return;}setup.plan.formats=set.filter(x=>x!==f);}else if(set.length<2)set.push(f);else{toast('Wähle höchstens zwei bevorzugte Übungsformen.');return;}render();return;}
    if(a==='quiz-choice'){setup.choices[setup.quizIndex]=Number(b.dataset.choice);render();return;}
    if(a==='setup-cancel'){setup=null;render();return;}
    if(a==='setup-back'){if(setup.step===2&&setup.quizIndex>0)setup.quizIndex--;else setup.step=Math.max(0,setup.step-1);render();window.scrollTo(0,0);return;}
    if(a==='setup-next'||a==='quiz-skip'){if(setup.step===0){const error=C.validatePlan(setup.plan);if(error){toast(error);return;}}if(setup.step===2&&setup.quizIndex<diagnostics.length-1)setup.quizIndex++;else setup.step++;render();window.scrollTo(0,0);return;}
    if(a==='setup-finish'){const diagnostic={};setup.choices.forEach((choice,i)=>{if(choice!==null)diagnostic[diagnostics[i].category]=choice===diagnostics[i].correct?1:0;});if(Object.keys(diagnostic).length)setup.plan.diagnostic=diagnostic;state.plan=setup.plan;state.onboarded=true;state=C.normalize(state,cards);setup=null;save();go('home');toast('Dein persönlicher Lernplan ist bereit.');}
  });
  document.addEventListener('input',e=>{const t=e.target;if(t.id==='worksheetAnswer'){Q.setText(state,worksheetId,t.value);save();$('worksheetCount').textContent=t.value.length+' / 12.000 Zeichen';worksheetFeedback();$('worksheetSave').textContent=storageWarning?'Speichern fehlgeschlagen – bitte Backup sichern':'Auf diesem Gerät gespeichert · Abgleich folgt';}if(t.classList.contains('worksheet-caption')){const e=Q.edit(state,worksheetId),image=e.images.find(i=>i.id===t.dataset.image);if(image){image.caption=t.value.slice(0,300);e.completed=false;save();worksheetFeedback();}}if(t.id==='catalogSearch'){filters.search=t.value;$('catalogResults').innerHTML=catalogResults();}if(t.id==='testAnswer'){const test=visibleTest();if(test?.status==='draft'){F.saveDraft(state,test.id,test.ids[test.position],t.value);save();$('testAnswerCount').textContent=t.value.length+' / 6.000 Zeichen';const answered=test.ids.filter(id=>test.entries[id].answer.trim()).length,repeats=F.summary(test).repeats,controls=F.summary(test).controls;$('testAnswered').textContent=` · ${answered} ${answered===1?'Antwort':'Antworten'} gespeichert${repeats?' · '+repeats+' '+(repeats===1?'Wiederholung':'Wiederholungen'):''}${controls?' · 1 Kontrollfrage':''}`;document.querySelectorAll('[data-action="test-position"]').forEach(b=>{const n=Number(b.dataset.position);b.textContent=String(n+1)+(test.entries[test.ids[n]].answer.trim()?' ✓':'');});const track=document.querySelector('.session-track i');if(track)track.style.width=answered/test.ids.length*100+'%';}}if(t.id==='scratchAnswer'&&session){session.scratch=t.value;if(session.mode==='write'){C.saveAnswer(state,session.ids[session.position],t.value);save();$('freeAnswerCount').textContent=t.value.length+' / 6.000 Zeichen';document.querySelectorAll('[data-action="check-answer"],[data-action="submit-answer"]').forEach(b=>b.disabled=t.value.trim().length<5);}}if(t.id==='cardNote'){const id=t.dataset.card;state.cards[id]={...C.cardState(state,id),note:t.value.slice(0,2000)};save();}if(t.id==='setupStart'&&setup){setup.plan.start=t.value;setupPlanPreview();}if(t.id==='setupDeadline'&&setup){if(!setup.plan.deadline&&t.value)setup.plan.reviewAuto=true;setup.plan.deadline=t.value||null;setupPlanPreview();}if(t.id==='examDeadline'||t.id==='examStart')examPreview();});
  document.addEventListener('change',e=>{const t=e.target;if(t.id==='worksheetImages'){uploadWorksheetImages(t);return;}if(t.id==='worksheetQuestion'){worksheetId=t.value;$('catalogResults').innerHTML=catalogResults();return;}if(t.id==='visualFilter'){filters.visual=t.value;$('catalogResults').innerHTML=catalogResults();return;}if(t.id==='chapterFilter'){filters.chapter=t.value;$('catalogResults').innerHTML=catalogResults();}if(t.id==='statusFilter'){filters.status=t.value;$('catalogResults').innerHTML=catalogResults();}if(t.id==='setupMinutes'&&setup){setup.plan.minutes=Number(t.value);setupPlanPreview();}if(t.id==='setupReview'&&setup){setup.plan.reviewAuto=t.value==='auto';if(t.value!=='auto')setup.plan.finalReviewDays=Number(t.value);setupPlanPreview();}if(['examMinutes','examReview'].includes(t.id))examPreview();if(t.id==='setupSession'&&setup)setup.plan.session=Number(t.value);if(t.id==='backupImport')importBackup(t.files[0]);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog')&&setup&&state.onboarded){setup=null;render();}});
  setInterval(()=>{if(!session||session.done||!$('sessionTimer'))return;if(session.mode==='speak'){const seconds=Math.max(0,60-Math.floor((Date.now()-session.cardStarted)/1000));$('sessionTimer').textContent=seconds?String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')+' · erklären':'In Ruhe zu Ende erklären';return;}if(session.mode!=='exam')return;const seconds=Math.max(0,900-Math.floor((Date.now()-session.started)/1000));$('sessionTimer').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(seconds===0){finish();toast('Die 15 Minuten sind vorbei. Deine Einschätzungen wurden zusammengefasst.');}},1000);
  if(!cards.length){$('app').innerHTML='<main class="empty-state"><h1>Die Lerninhalte fehlen.</h1><p>Bitte die Seite erneut laden oder das vollständige App-Paket verwenden.</p></main>';return;}
  if(location.protocol!=='file:'){
    syncController=window.LernpassSync.create({key:KEY,storage:localStorage,getState:()=>state,normalize:value=>C.normalize(value,cards),canApply:()=>booting||(!imageUpload&&!grading&&!session&&!setup&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)),applyState:next=>{
      try{localStorage.setItem(KEY,JSON.stringify(next));}catch{toast('Der Browser kann den Lernstand nicht speichern. Bitte ein Backup sichern.');return false;}
      state=next;session=null;setup=null;render();return true;
    },onStatus:updateSyncStatus});
    render();syncController.start().finally(()=>{booting=false;render();aiStatus();});
    setInterval(()=>{if(document.visibilityState==='visible')syncController.refresh();},20000);
    window.addEventListener('online',()=>syncController.refresh());
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncController.refresh();});
  }else render();
  if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('sw.js').catch(()=>{});
})();
